from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2316';_,c=card(i);refs=c['references'];refs[0]['locator']='SWAT 2024, article 38: Section 2.2, Proposition 2 and final question in Section 5 read. The task includes constructing a decomposition and rejecting graphs whose mim-width exceeds one.'
refs.append(dict(id='hardness2026',title='On the Hardness of Recognizing Graphs of Small Mim-Width and Its Variants',authors='Max Dupré la Tour, Manuel Lafond, Ndiamé Ndiaye',year=2026,url='https://doi.org/10.4230/LIPIcs.ICALP.2026.83',locator='ICALP 2026, article 83: Theorems 1–2, introduction and Section 5 read. Recognizing mim-width at most two is NP-complete; width-one mim-width and linear mim-width recognition remain explicitly open. Hardness at one for the other variants does not cover mim-width.'))
save(i,dict(title='Recognizing and constructing mim-width-one decompositions',formal='Is there a deterministic polynomial-time algorithm that, on any finite graph G, either outputs a branch decomposition of mim-width at most one or correctly reports that no such decomposition exists?',definitions='G=(V,E) is a finite undirected simple graph with n=|V|. For A⊆V, the cut graph G[A,V∖A] keeps exactly those edges with one endpoint in each side; edges internal to either side are discarded. An induced matching in this bipartite graph is a set of vertex-disjoint edges whose endpoints induce exactly those matching edges. Let mim_G(A) be its maximum size. A branch decomposition (T,L) consists of a tree T whose internal nodes have degree three and a bijection L from V to the leaves of T. Deleting a tree edge splits its leaves and hence V into A and V∖A. The decomposition width is the maximum mim_G(A) over its tree-edge cuts. The graph’s mim-width is the minimum over all such decompositions. The target is a decomposition of width ≤1, including width zero for edgeless graphs; empty and one-vertex graphs have the trivial width-zero convention. Runtime is polynomial in the ordinary explicit graph input size. No decomposition or bounded-width promise is supplied. The tree need not be a caterpillar: restricting it to one would instead ask about linear mim-width.',question_type='yes_no',answer_criterion='Construct an algorithm that returns a valid width-at-most-one decomposition on every yes-instance and rejects every no-instance in polynomial time, or establish an obstruction to this guarantee. Algorithms using a supplied decomposition, recognizing only a subclass, or deciding width at most two do not settle the question.',context_blocks=[b('What a width-one cut forbids','Across every cut in the chosen tree, there cannot be two disjoint crossing edges with both cross-pair edges absent. Edges inside a side do not affect this test. Equivalently, every cut graph must be a bipartite chain graph.', 'primary'),b('The missing decomposition limits algorithmic use','Many graph problems become tractable when a small-mim-width decomposition is available. The source even shows new polynomial-time algorithms at width one, but those guarantees assume the decomposition is supplied.', 'primary'),b('The tree is part of the output','Testing the cuts of one given tree is different from finding a tree whose every cut is good. The recognition question must succeed or reject on an arbitrary input graph.'),b('The recent hardness result stops at width two','The ICALP 2026 paper proves NP-completeness for recognizing mim-width at most two and for width-one recognition of several related parameters. It explicitly leaves ordinary mim-width one open, so those results do not settle this card.', 'hardness2026')],why='Would determine whether the especially useful width-one case can be detected and decomposed efficiently, making its decomposition-based algorithms available on arbitrary input graphs.',progress=[dict(date='2024',text='The SWAT paper gives algorithms using width-one decompositions and repeats the recognition/construction problem.',citation='primary'),dict(date='2026',text='ICALP 2026 proves hardness at mim-width two while explicitly preserving the width-one question.',citation='hardness2026')],references=refs,status='source_open',status_note='Original cut/decomposition definitions and the complete question checked against the ICALP 2026 hardness theorems and open-problems section. No width-one resolution was located through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'A foundational recognition problem for using small-mim-width graph algorithms.'),review_note='Recovered the missing output and negative conclusion, defined induced matchings in the crossing-edge graph, and retained arbitrary branch trees rather than substituting linear mim-width.',working_summary=sm(['The task is to find a branch decomposition whose every cut has no induced matching of size two.','Only edges crossing a cut count toward its mim-width.','The algorithm must also recognize when no such tree exists.','Known width-one graph algorithms usually assume the tree has already been given.','New hardness results reach width two and related width-one parameters, while ordinary mim-width one remains open.'],['primary','hardness2026'])),notes=['Recovered recognition plus decomposition output and handled width-zero graphs.','Defined cut-induced matching, branch-tree width and the minimization over trees.','Added the exact scope of ICALP 2026 hardness and its explicit remaining width-one question.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2512.06186'])

i='TCS-2336';_,c=card(i);refs=c['references'];refs[0]['locator']='COLT 2023, PMLR 195: online regret definition, Definition 2, Theorems 1 and 4, Open Problem 1 and Section 4.1/Theorems 8–9 read. The target is Θ(sqrt(L(H)T)) for T≥L(H), with universal constants independent of label-space size.'
save(i,dict(title='Sharp multiclass online regret without logarithmic factors',formal='Does a universal constant C exist such that every multiclass hypothesis class H of finite Littlestone dimension d≥1 admits, for every horizon T≥d, an online learner with worst-case expected regret at most C√(dT)? A matching universal Ω(√(dT)) lower bound is already known. The guarantee must not depend on the number of labels, which may be infinite.',definitions='Let X be an instance set, Y a label set and ∅≠H⊆Y^X a known hypothesis class. On round t an adversary presents x_t∈X, the learner chooses a probability distribution p_t on Y, and the adversary then reveals y_t∈Y. The learner suffers loss 1−p_t(y_t), the probability of a wrong randomized prediction. It observes the actual label, not just whether its prediction was correct. Its regret is Σ_{t=1}^T(1−p_t(y_t))−min_{h∈H}Σ_{t=1}^T1[h(x_t)≠y_t]. Let R_T(H) be the infimum over learner strategies of the supremum of this regret over adversarial plays; the adversary may observe p_t before choosing y_t. This distribution-valued convention already accounts for prediction randomness. There is no computational-efficiency restriction on a strategy, and it may know T. A depth-d Littlestone tree is a complete binary tree with an instance x∈X at each internal node and two distinct labels from Y on its two outgoing edges. It is shattered by H if every root-to-leaf path has some h∈H whose labels on the encountered instances equal all the path’s edge labels. The Littlestone dimension L(H) is the greatest shattered depth, or infinity if depths are unbounded. The question asks R_T(H)≤C√(L(H)T) with one numerical C valid for all H,X,Y and T≥L(H)≥1. If L(H)=0 all hypotheses agree pointwise and zero regret is attainable; for T<d a bound must be capped at T, so the displayed two-sided asymptotic target is stated only for T≥d.',question_type='yes_no',answer_criterion='Prove the universal label-independent O(√(dT)) upper bound, or give classes and horizons with unbounded ratio R_T(H)/√(dT). Removing a factor depending on T while retaining a factor depending on |Y| does not give the requested universal bound.',context_blocks=[b('Regret compares against the best fixed predictor','The labels need not be consistent with any h∈H. The learner is charged only for its excess expected mistakes over the best one fixed hypothesis chosen after the whole sequence is known.'),b('Finiteness of the dimension already characterizes learnability','The 2023 paper proves sublinear regret for every finite-Littlestone-dimension multiclass class, even with infinitely many labels. The remaining question is the sharp rate, not whether such classes are learnable at all.', 'primary'),b('The current general bound has a square-root logarithmic gap','The source gives O(√(dT log(eT/d))) regret, compared with the known Ω(√(dT)) lower bound. Writing Θ(dT) would lose the square root and describe a fundamentally different claim.', 'primary'),b('A bound for finitely many labels still has a price','For finite Y the source also obtains O(√(dT log|Y|)). This yields the desired rate when |Y| is a fixed constant, but its hidden coefficient grows with the label count. The conjecture asks for a numerical constant independent of that count.', 'primary')],why='Would determine whether Littlestone dimension alone controls the exact minimax cost of multiclass sequential prediction, beyond the already known learnability characterization.',progress=[dict(date='2023',text='The source proves label-independent regret within a square-root logarithmic factor of the lower bound and asks to remove that factor.',citation='primary'),dict(date='2023',text='For finite label spaces, the same paper removes the horizon logarithm at the cost of a log|Y| factor under the square root.',citation='primary')],references=refs,status='source_open',status_note='The original game, dimension, horizon range and both upper bounds were checked. Later-result searches, the source’s arXiv version record and the May 2026 oracle-efficiency paper were checked through 12 September 2026. The latter explicitly studies binary classification; no resolution of the universal multiclass constant was located.',model_self_contained=True,requires_context=False,importance=imp(c,'A sharp minimax characterization of multiclass online prediction by a combinatorial dimension.'),review_note='Restored the missing square root and the T≥d regime. Defined the full-information adversarial game and required constants independent of the label set; separated finite-label, transductive and binary-oracle results.',working_summary=sm(['The learner predicts one of potentially infinitely many labels and is compared with the best fixed hypothesis in hindsight.','Finite Littlestone dimension already guarantees sublinear regret.','The open target is a sharp bound proportional to √(dimension × rounds), with one universal constant.','The known general upper bound has an extra square-root logarithmic factor.','A finite-label bound trades that factor for dependence on the number of labels, so it does not settle the universal question.'],['primary'])),notes=['Restored the square-root regret target and meaningful horizon range.','Defined full-information play, prediction distributions, comparator and Littlestone trees.','Made universality over label spaces explicit and separated the two known upper bounds.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2303.17716','https://arxiv.org/abs/2605.07155'])
